'use client';

// Vendored from MerchFlow Charts components/web/ReportDashboard.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { useState, type ReactNode } from 'react';
import { gms } from '@/lib/merch-flow-report/brand/tokens';
import { units } from '@/lib/merch-flow-report/format';
import { type Product, type TourReport, DEFAULT_OPTIONS } from '@/lib/merch-flow-report/report/types';
import { decorate } from '@/lib/merch-flow-report/report/derive';
import { SummarySection } from './SummarySection';
import { ShowRows } from './ShowRows';
import { Scorecard } from './Scorecard';
import { CategoryMix } from './CategoryMix';
import { ProductDrawer } from './ProductDrawer';
import { ReportHeader, ReportBottomBar } from './ReportChrome';
import { LinkButton } from '@/components/merch-flow-report/ui';

/**
 * The shareable report: an interactive dashboard, not a scaled-down PDF.
 *
 * Section titles are plain and descriptive; subtitles explain only how to read
 * the page. The A3 PDF is a separate rendering of the same TourReport.
 */

/** Tracker: guided-tour anchors on the panels. */
const TOUR_ANCHORS: Record<string, string> = { products: 'mf-scorecard', mix: 'mf-category' };

function Panel({
  id,
  title,
  children,
}: {
  id: string;
  title: string;
  children: ReactNode;
}) {
  return (
    <section id={id} data-tour={TOUR_ANCHORS[id]} className="mt-5 scroll-mt-16 rounded bg-white p-4 sm:p-7">
      <h2 className="text-[15px] font-bold uppercase tracking-tight sm:text-[17px]">
        {title}
      </h2>
      <div className="mt-4">{children}</div>
    </section>
  );
}

export function ReportDashboard({
  report: raw,
  imageUrls,
  artistLogoUrl,
  pdfHref,
  pdfLabel,
}: {
  report: TourReport;
  imageUrls: Record<string, string>;
  artistLogoUrl?: string;
  pdfHref: string;
  /** Tracker: label for the PDF links (Charts says "Download PDF"). */
  pdfLabel?: string;
}) {
  const [selected, setSelected] = useState<Product | null>(null);

  const options = raw.options ?? DEFAULT_OPTIONS;
  const report: TourReport = {
    ...raw,
    options,
    products: raw.products.map(decorate),
  };

  const ranked = [...report.products].sort((a, b) => b.unitsSold - a.unitsSold);

  return (
    <div className="min-h-full" style={{ background: '#F7F7F8' }}>
      <ReportHeader artist={report.artist} tourName={report.tourName} pdfHref={pdfHref} pdfLabel={pdfLabel} />

      <header style={{ background: gms.black }}>
        <div className="mx-auto w-full max-w-6xl px-4 py-6 sm:px-8 sm:py-10">
          <div className="flex items-center justify-between gap-4">
            <div className="rounded bg-white px-3 py-2">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src="/gms-logo.png"
                alt="Global Merchandising Services"
                className="h-5 w-auto"
              />
            </div>
            {artistLogoUrl && (
              /* eslint-disable-next-line @next/next/no-img-element */
              <img
                src={artistLogoUrl}
                alt={report.artist}
                className="h-9 w-auto object-contain sm:h-12"
              />
            )}
          </div>

          <p
            className="mt-6 text-[10px] font-bold uppercase tracking-[0.28em]"
            style={{ color: gms.red }}
          >
            Tour Sales Chart
          </p>
          <h1
            className="mt-2 text-[26px] font-extrabold uppercase leading-[1.02] tracking-tight text-white sm:text-[42px]"
            style={{ fontFamily: 'var(--font-display)' }}
          >
            {report.artist}
          </h1>
          <p
            className="mt-2 text-[12px] uppercase tracking-[0.1em] sm:text-[15px]"
            style={{ color: gms.mist }}
          >
            {report.tourName}
            {report.dateRange ? ` · ${report.dateRange}` : ''}
          </p>

          <LinkButton
            href={pdfHref}
            data-tour="charts-link"
            className="mt-6 !bg-white !text-[#111214] hover:!bg-[#E7E9EC]"
          >
            {pdfLabel ?? 'Download A3 PDF'}
          </LinkButton>
        </div>
      </header>

      <main className="mx-auto w-full max-w-6xl px-3 py-5 sm:px-8 sm:py-8">
        <Panel id="summary" title="Tour Summary">
          <SummarySection report={report} imageUrls={imageUrls} onSelect={setSelected} />
        </Panel>

        <Panel id="shows" title="Gross Sales & Per Heads by Show">
          <ShowRows shows={report.shows} />
        </Panel>

        <Panel id="products" title="Product Sales">
          <Scorecard
            products={report.products}
            attendance={report.attendance}
            tailThreshold={options.tailThreshold}
            imageUrls={imageUrls}
            onSelect={setSelected}
          />
        </Panel>

        <Panel id="mix" title="Category Mix & Product Ratios">
          <CategoryMix products={report.products} attendance={report.attendance} />
        </Panel>

        <Panel id="all-products" title="All Products">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[520px] border-collapse">
              <thead>
                <tr style={{ background: gms.black }}>
                  {['Product', 'Tracker name', 'SKU', 'Units', 'Stock'].map((h) => (
                    <th
                      key={h}
                      className="px-3 py-2 text-left text-[10px] font-bold uppercase tracking-[0.1em] text-white"
                    >
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {ranked.map((product, i) => (
                  <tr
                    key={product.sku}
                    style={{ background: i % 2 ? gms.surface : '#fff' }}
                  >
                    <td className="px-3 py-1.5 text-[12px] font-medium">
                      {product.displayName ?? product.name}
                    </td>
                    <td className="px-3 py-1.5 text-[11px]" style={{ color: gms.slate }}>
                      {product.name}
                    </td>
                    <td className="tnum px-3 py-1.5 text-[11px]" style={{ color: gms.mist }}>
                      {product.sku}
                    </td>
                    <td className="tnum px-3 py-1.5 text-[12px]">{units(product.unitsSold)}</td>
                    <td className="tnum px-3 py-1.5 text-[11px]" style={{ color: gms.slate }}>
                      {product.closingStock !== undefined ? units(product.closingStock) : '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Panel>

        <footer
          className="mt-6 flex flex-wrap items-center justify-between gap-3 px-1 text-[10px] uppercase tracking-[0.16em]"
          style={{ color: gms.mist }}
        >
          <span>
            {report.shows.length} shows · {report.products.length} products
          </span>
          <a href={pdfHref} className="underline">
            {pdfLabel ?? 'Download A3 PDF'}
          </a>
        </footer>
      </main>

      <ReportBottomBar pdfHref={pdfHref} pdfLabel={pdfLabel} />

      <ProductDrawer
        product={selected}
        imageUrl={selected ? imageUrls[selected.sku] : undefined}
        attendance={report.attendance}
        rank={selected ? ranked.findIndex((p) => p.sku === selected.sku) + 1 : undefined}
        total={ranked.length}
        onClose={() => setSelected(null)}
      />
    </div>
  );
}
